#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> maxNumOfSubstrings(std::string s) {
        std::vector<int> first(26, -1), last(26, -1);
        for (int i = 0; i < (int)s.size(); ++i) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        std::vector<std::pair<int, int>> intervals;
        for (int c = 0; c < 26; ++c) {
            if (first[c] == -1) continue;
            int l = first[c], r = last[c];
            bool valid = true;
            for (int i = l; i <= r; ++i) {
                int ch = s[i] - 'a';
                if (first[ch] < l) {
                    valid = false;
                    break;
                }
                r = std::max(r, last[ch]);
            }
            if (valid) intervals.push_back({r, l});
        }
        std::sort(intervals.begin(), intervals.end());
        std::vector<std::string> ans;
        int prevR = -1;
        for (auto& [r, l] : intervals) {
            if (l > prevR) {
                ans.push_back(s.substr(l, r - l + 1));
                prevR = r;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<String> maxNumOfSubstrings(String s) {
        int[] first = new int[26];
        int[] last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        List<int[]> intervals = new ArrayList<>();
        for (int c = 0; c < 26; c++) {
            if (first[c] == -1) continue;
            int l = first[c], r = last[c];
            boolean valid = true;
            for (int i = l; i <= r; i++) {
                int ch = s.charAt(i) - 'a';
                if (first[ch] < l) {
                    valid = false;
                    break;
                }
                r = Math.max(r, last[ch]);
            }
            if (valid) intervals.add(new int[]{r, l});
        }
        intervals.sort((a, b) -> Integer.compare(a[0], b[0]));
        List<String> ans = new ArrayList<>();
        int prevR = -1;
        for (int[] inv : intervals) {
            if (inv[1] > prevR) {
                ans.add(s.substring(inv[1], inv[0] + 1));
                prevR = inv[0];
            }
        }
        return ans;
    }
}

var maxNumOfSubstrings = function(s) {
    const first = new Array(26).fill(-1);
    const last = new Array(26).fill(-1);
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i) - 97;
        if (first[c] === -1) first[c] = i;
        last[c] = i;
    }
    const intervals = [];
    for (let c = 0; c < 26; c++) {
        if (first[c] === -1) continue;
        let l = first[c], r = last[c];
        let valid = true;
        for (let i = l; i <= r; i++) {
            const ch = s.charCodeAt(i) - 97;
            if (first[ch] < l) {
                valid = false;
                break;
            }
            r = Math.max(r, last[ch]);
        }
        if (valid) intervals.push([r, l]);
    }
    intervals.sort((a, b) => a[0] - b[0]);
    const ans = [];
    let prevR = -1;
    for (const [r, l] of intervals) {
        if (l > prevR) {
            ans.push(s.substring(l, r + 1));
            prevR = r;
        }
    }
    return ans;
};
